def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.
    """
    def decorator(func):
        cache_key = key(func)  # Hash key used for dictionary
        cache_value = cache.get(cache_key, None)  # Fetch cache entry

        def wrapped(*args, **kwargs):
            if cache_value is not None:
                func(*args, **kwargs)  # Proceed with cached value

            with lock:
                cache_value = cache.get(cache_key, None)  # Recompute only if the cache was stale
                if cache_value is None:
                    result = func(*args, **kwargs)  # Execute function
                    cache[cache_key] = result  # Caching the result
                else:
                    func(*args, **kwargs)
            return result

        return wrapped

    return decorator
