def difference(d1, d2, level=-1, visited=None):
    if visited is None:
        visited = {}

    if level == 0 or id(d1) in visited:
        return d1

    for key in d1:
        if key not in d2 and id(d1[key]) not in visited:
            visited[id(d1[key])] = True
            d1[key] = difference(d1[key], d2, level-1, visited)

    for key in d2:
        if key in d1 and id(d1[key]) not in visited:
            visited[id(d1[key])] = True

    return {k: v for k, v in d1.items() if v is not None}
