def _include_groups(self, parser_dict):
    """
    Resolves the include dict directive in the spec files.

    :param parser_dict: Dictionary where section name is the key and section itself is the value.
    :return: Newly constructed parser dictionary where include statements have been replaced with actual sections.
    """
    for section_name, section_content in parser_dict.items():
        if section_name.lower() == 'include':
            include_file = section_content.strip()
            try:
                with open(include_file, 'r') as file:
                    included_content = file.read()
                    parser_dict[section_name] = included_content
            except FileNotFoundError:
                raise ValueError(f"Includes '{include_file}' not found.")
            except Exception as e:
                raise ValueError(f"Failed to read includes '{include_file}': {e}")
    return parser_dict
